import{z as A,x as d,o as n,c,q as i,j as l,D as o,d as a,s as t,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"源码编码与 Unicode 词法","description":"","frontmatter":{"title":"源码编码与 Unicode 词法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/source-encoding-lexing.md","filePath":"cs/source-encoding-lexing.md","lastUpdated":1791413859000}'),B={name:"cs/source-encoding-lexing.md"};function p(C,e,D,F,u,h){const r=d("Mermaid");return n(),c("div",null,[e[2]||(e[2]=i('<h1 id="源码编码与-unicode-词法" tabindex="-1">源码编码与 Unicode 词法 <a class="header-anchor" href="#源码编码与-unicode-词法" aria-label="Permalink to &quot;源码编码与 Unicode 词法&quot;">​</a></h1><div class="epigraph"><p>词法的字母表不是「字节」。规范化、BOM、同形字与标识符字符类决定两个源文件是不是同一个程序。</p><footer>—— 据 Unicode 标准标识符附录；ISO C/C++ 通用字符名；Peyton Jones 等对 Haskell 词法的讨论整理</footer></div><p>上一课<a href="/cs/c-preprocessor">C 预处理器</a>假定已经有了「记号」。更早的翻译阶段是<strong>物理编码</strong>：UTF-8、续行、三字符组（历史）、通用字符名 <code>\\uXXXX</code>。主干<a href="/cs/regex-lexer">正则与词法</a>用 ASCII 讲最长匹配。缺口是<strong>字母表真正是什么</strong>，以及 lex 规则在 Unicode 下如何仍保持确定扫描。本课收束前端进阶课序，不重写 UTF-8 编解码课的全部位模式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一标识符可有预组合与分解形式（NFC/NFD）。语言必须规定：先规范化再比较，还是按字节比较。BOM 在文件头不是标识符。零宽字符可把两个看起来一样的名字拆开——工具链要不要拒。缺口是<strong>词法字母表与等价</strong>，不是再画 DFA 子集构造。</p><p>flex 默认字节；要认 Unicode 标识符需字符类与编码转换，否则正则 <code>.</code> 的意义漂在 UTF-8 续字节上。</p><p><span class="marginnote">术语翻译：BOM 就是文件开头多出的一个特殊码点 U+FEFF，原本用来声明字节序；在 UTF-8 里它没有字节序可声明，词法器要把它当可忽略的前导标记处理，而不是标识符的一部分。漏掉这一步，文件第一个「标识符」会多出一个看不见的字符。</span></p><h3 id="同形字不是正则冲突" tabindex="-1">同形字不是正则冲突 <a class="header-anchor" href="#同形字不是正则冲突" aria-label="Permalink to &quot;同形字不是正则冲突&quot;">​</a></h3><p><code>latin a</code> 与 <code>cyrillic а</code> 是不同码点，DFA 可以区分。人不可区分。这是诊断与安全策略，不是 NFA 等价问题。不要用「加一条正则」假装解决。</p><p><span class="marginnote">数字实例：é 可以是单码点 U+00E9（UTF-8 占 2 字节），也可以是 e 加组合符 U+0301（共 3 字节）。按字节比较必判为两个不同名字；先做 NFC 归一，两者收成同一形式，编译器才有一致的判定。规范化与不规范化都合法，但必须由语言标准钉死一种。</span></p><p><span class="marginnote">Unicode UAX #31（标识符）。C++ 的 UCN 与 raw string 改变词法最长匹配。本课不进入显示层 Bidirectional 全部算法，只点名源码欺骗（Trojan Source）是词法+渲染问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规定源编码（或探测 UTF-8）。解码为码点流，再跑词法 DFA。标识符：<code>XID_Start</code>/<code>XID_Continue</code> 或语言自己的表。字符串字面量：转义、原始字符串、换行规则与 lex 起始条件（<a href="/cs/lex-flex">lex</a>）对齐。</p>',13)),(n(),l(s,null,{default:o(()=>[t(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20BYTES%5B%22%E5%AD%97%E8%8A%82%22%5D%20--%3E%20DEC%5B%22%E8%A7%A3%E7%A0%81%E4%B8%BA%E7%A0%81%E7%82%B9%22%5D%0A%20%20DEC%20--%3E%20NORM%5B%22%E5%8F%AF%E9%80%89%E8%A7%84%E8%8C%83%E5%8C%96%22%5D%0A%20%20NORM%20--%3E%20DFA%5B%22%E8%AF%8D%E6%B3%95%20DFA%22%5D%0A%20%20DFA%20--%3E%20TOK%5B%22%E8%AE%B0%E5%8F%B7%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("p",null,[a("cpp 的 "),E("code",null,"\\u"),a(" 发生在特定阶段，可能在规范化之前或之后——必须按语言标准钉死，不能凭直觉。")],-1)),e[4]||(e[4]=E("h2",{id:"机制",tabindex:"-1"},[a("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=E("p",null,"最长匹配在码点上，不在字节上：多字节字符不能从中切开。错误恢复跳过非法 UTF-8 序列时，行号与列要按语言的列定义（码点或显示宽）报告。",-1)),(n(),l(s,null,{default:o(()=>[t(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E4%B8%A4%E6%AE%B5%E7%9C%8B%E8%B5%B7%E6%9D%A5%E7%9B%B8%E5%90%8C%E7%9A%84%E6%A0%87%E8%AF%86%E7%AC%A6%22%5D%20--%3E%20ENC%5B%22%E5%85%88%E6%A0%B8%E7%BC%96%E7%A0%81%EF%BC%9A%E5%90%88%E6%B3%95%20UTF-8%20%E5%BA%8F%E5%88%97%3F%22%5D%0A%20%20ENC%20--%3E%20CP%5B%22%E8%A7%A3%E7%A0%81%E4%B8%BA%E7%A0%81%E7%82%B9%E6%B5%81%22%5D%0A%20%20CP%20--%3E%20NORM%5B%22%E6%8C%89%E8%AF%AD%E8%A8%80%E6%A0%87%E5%87%86%E5%81%9A%E8%A7%84%E8%8C%83%E5%8C%96%EF%BC%88%E6%88%96%E8%A7%84%E5%AE%9A%E4%B8%8D%E8%A7%84%E8%8C%83%E5%8C%96%EF%BC%89%22%5D%0A%20%20NORM%20--%3E%20CMP%5B%22%E9%80%90%E7%A0%81%E7%82%B9%E6%AF%94%E8%BE%83%22%5D%0A%20%20CMP%20--%3E%20EQ%5B%22%E7%9B%B8%E7%AD%89%EF%BC%9A%E6%98%AF%E5%90%8C%E4%B8%80%E6%A0%87%E8%AF%86%E7%AC%A6%22%5D%0A%20%20CMP%20--%3E%20CONF%5B%22%E4%B8%8D%E7%AD%89%E4%BD%86%E8%A7%86%E8%A7%89%E7%9B%B8%E5%90%8C%EF%BC%9A%E5%90%8C%E5%BD%A2%E5%AD%97%22%5D%0A%20%20CONF%20--%3E%20POL%5B%22%E4%BA%A4%E7%94%B1%E5%AE%89%E5%85%A8%E7%AD%96%E7%95%A5%EF%BC%9A%E5%91%8A%E8%AD%A6%E6%88%96%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=i('<p>这张图回答的是：判定「两个名字是否相同」要过几道关卡——编码合法性、规范化策略、码点比较，最后剩下的视觉相同才是安全策略的领地。</p><p>PEG/Pratt 若直接吃字节，会把 UTF-8 当运算符碎片。前端进阶课序到此：生成器、通用分析、宏、编码——下一单元从无类型 λ 走到类型。</p><p><span class="marginnote">直觉类比：同形字像两个长得一模一样的双胞胎，各拿各的身份证。DFA 认身份证（码点），人认脸（渲染结果）。所以这类问题归安全策略管——加一条正则是在用改脸的方式冒充换证，方向就错了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写字体渲染，不规定编辑器是否做 confusable 警告。后课默认：词法字母表是码点（或标准规定的规范化码点）。下一课<a href="/cs/simply-typed-lambda">简单类型 λ</a> 接主干 λ 与类型检查，不再处理 BOM。</p><p>也不把 GBK 与 UTF-8 混用当可移植源。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>词法在码点（及规定的规范化）上跑，不在生字节上。</li><li>Unicode 标识符类与同形字是不同层。</li><li>与 lex/cpp 的阶段顺序必须按语言标准。</li><li>出处：Unicode UAX #31；ISO C/C++ 词法；对照 Thompson/龙书正则词法。</li></ul>',8))])}const T=A(B,[["render",p]]);export{f as __pageData,T as default};
